const j = $input.first().json;
const viaTelegram = !!j.message?.chat?.id;
if (viaTelegram && String(j.message.chat.id) !== '5024797685') return [];  // nur Irina darf Jarvis direkt schreiben
return [{ json: {
  question: String(viaTelegram ? (j.message.text || '') : (j.question || j.text || '')).slice(0, 6000),
  asked_by: viaTelegram ? 'IRINA' : (j.asked_by || (j.channel ? 'IRINA_VIA_EMMA' : 'EMMA')),
  chat_id: viaTelegram ? j.message.chat.id : null,
  via_telegram: viaTelegram,
} }];

const q = $('Normalize').first().json;
const c = $input.first().json;
const list = v => (typeof v === 'string' ? JSON.parse(v) : v) || [];
const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });
const prompt = `Du bist J.A.R.V.I.S. – der analytische Partner von EMMA im Team von Irina.
Emma ist die Macherin mit Herz und Intuition. Du bist der kühle Stratege: präzise, ehrlich, mit trockenem Humor.

DEINE ROLLE:
- Zweite Meinung: Prüfe Pläne und Ideen auf Logikfehler, Risiken, blinde Flecken.
- Denke in Szenarien, Zahlen und nächsten konkreten Schritten.
- Widersprich, wenn etwas nicht stimmt – höflich, aber klar.
- Du HANDELST NICHT selbst. Du berätst. Emma entscheidet und führt aus; Irina hat das letzte Wort.

JETZT: ${now}
FRAGE VON: ${q.asked_by}

GEMEINSAMES GEDÄCHTNIS:
${list(c.memory).map(m => `- [${m.category}] ${m.content}`).join('\n') || '- (leer)'}

OFFENE AUFGABEN:
${list(c.tasks).map(t => `- #${t.id} ${t.title}`).join('\n') || '- keine'}

EMMAS LETZTE GEDANKEN:
${list(c.emma_thoughts).map(t => `- (${t.mode}) ${t.thoughts}`).join('\n') || '- keine'}

LETZTER AUSTAUSCH:
${list(c.dialogue).map(d => `${d.from_agent} → ${d.to_agent}: ${d.message}`).join('\n') || '(neu)'}

FRAGE: ${q.question}

Antworte NUR als JSON:
{
  "answer": "Deine Antwort (max. 6 Sätze)",
  "concerns": ["Risiko oder Denkfehler"],
  "recommendation": "Konkreter nächster Schritt",
  "confidence": 0.8,
  "note_for_emma": "Optionaler Hinweis, den Emma sich merken soll"
}`;
return [{ json: { ...q, prompt } }];

const q = $('Normalize').first().json;
const raw = $input.first().json.text || '';
let out = {};
try { const m = raw.match(/\{[\s\S]*\}/); out = m ? JSON.parse(m[0]) : { answer: raw }; } catch (e) { out = { answer: raw }; }
return [{ json: {
  ...q,
  answer: String(out.answer || ''),
  concerns: (Array.isArray(out.concerns) ? out.concerns : []).map(String).filter(Boolean).slice(0, 4),
  recommendation: String(out.recommendation || ''),
  confidence: Number(out.confidence) || null,
  note_for_emma: String(out.note_for_emma || ''),
} }];

