WITH q AS (
  INSERT INTO agent_dialogue (from_agent, to_agent, message) VALUES ($1, 'JARVIS', $2)
), a AS (
  INSERT INTO agent_dialogue (from_agent, to_agent, message, meta) VALUES ('JARVIS', $1, $3, $4::jsonb)
), note AS (
  INSERT INTO emma_memory (category, content, importance, source) SELECT 'learnings', $5, 3, 'JARVIS' WHERE $5 <> ''
)
SELECT 1 AS logged;
